script:
def walk(path):
    out = []
    for name in repo.list(path):
        p = path + "/" + name
        if name.endswith("/"):
            out.extend(walk(p[:-1]))
        else:
            out.append(p)
    return out

files = walk("src")
changed = []
for f in files:
    content = repo.read(f)
    if "slow_path" in content:
        new = content.replace("slow_path", "fast_path")
        repo.write(f, new)
        changed.append(f)
return {"files": files, "changed": changed, "diff": repo.diff()}
